public class InnerMailManagerIngressPointNetworkConfigurationFactory(Action<Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration>
{

    internal InnerMailManagerIngressPointPublicNetworkConfigurationFactory PublicNetworkConfigurationFactory { get; set; }

    internal InnerMailManagerIngressPointPrivateNetworkConfigurationFactory PrivateNetworkConfigurationFactory { get; set; }

    protected override Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration Create()
    {
        var networkConfigurationResult = CreateNetworkConfiguration();
        factoryAction?.Invoke(networkConfigurationResult);

        return networkConfigurationResult;
    }

    private Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration CreateNetworkConfiguration()
    {
        var networkConfigurationResult = new Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration();

        return networkConfigurationResult;
    }
    public override void CreateChildren(Humidifier.SES.MailManagerIngressPointTypes.NetworkConfiguration result)
    {
        base.CreateChildren(result);

        result.PublicNetworkConfiguration ??= PublicNetworkConfigurationFactory?.Build();
        result.PrivateNetworkConfiguration ??= PrivateNetworkConfigurationFactory?.Build();
    }

} // End Of Class

